{
  "private": true,
  "type": "module",
  "devDependencies": {
    "vize": "0.641.0",
    "tsrs": "0.20.1-ts7.1.0-beta",
    "vue": "3.5.43"
  }
}

import { ref, watch, type Ref } from "vue";

export function useBox(): [el: Ref<HTMLElement | undefined>] {
  const el = ref<HTMLElement>();
  watch(el, (value) => console.log(value?.clientWidth));
  return [el];
}

